<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Barangay Reports | TABACARE</title>
    <style>
        .sidebar { position: sticky; top: 0; height: 100vh; }
        :root{--ink:#1d2935;--muted:#70808b;--paper:#f4f7f8;--panel:#fff;--line:#e1e8eb;--teal:#0f766e;--nav:#172331;--shadow:0 14px 36px rgba(27,45,61,.08)}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,'Times New Roman',serif}.shell{min-height:100vh;display:grid;grid-template-columns:260px 1fr}.sidebar{display:flex;flex-direction:column;min-height:100vh;padding:22px 13px;background:var(--nav);color:#d9e3ea}.brand{display:flex;align-items:center;gap:11px;padding:5px 12px 28px;border-bottom:1px solid rgba(255,255,255,.08)}.mark{width:38px;height:38px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.4);border-radius:10px;color:#70ddd0;font:24px Arial}.brand strong{display:block;color:#fff;font:800 16px Arial;letter-spacing:.08em}.brand small{color:#91a7b5;font:10px Arial;letter-spacing:.08em;text-transform:uppercase}.label{padding:25px 12px 9px;color:#8094a2;font:700 10px Arial;letter-spacing:.13em;text-transform:uppercase}.nav{display:grid;gap:5px}.nav a{display:flex;align-items:center;gap:11px;padding:12px;border-radius:8px;color:#aabac5;text-decoration:none;font:600 14px Arial}.nav a:hover,.nav a.active{background:rgba(20,184,166,.14);color:#6ee7d8}.nav-icon{width:20px;text-align:center}.side-footer{margin-top:auto;padding:16px 12px 4px;border-top:1px solid rgba(255,255,255,.08);color:#8da1ad;font:12px/1.5 Arial}.main{min-width:0;padding:30px clamp(20px,4vw,58px) 48px}.topbar{display:flex;justify-content:space-between;gap:20px;margin-bottom:28px}.eyebrow{color:var(--teal);font:700 11px Arial;letter-spacing:.16em;text-transform:uppercase}h1{margin:7px 0 6px;font-size:clamp(28px,4vw,40px);font-weight:400}.intro{margin:0;color:var(--muted);font-size:16px}.profile{display:flex;align-items:center;gap:10px;color:var(--muted);font:13px Arial}.avatar{width:39px;height:39px;display:grid;place-items:center;border-radius:50%;background:#f2d18b;color:#65491a;font-weight:700}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.summary-card{padding:20px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow)}.summary-label{display:block;color:var(--muted);font:700 10px Arial;letter-spacing:.1em;text-transform:uppercase}.summary-value{display:block;margin-top:12px;color:var(--teal);font-size:32px}.panel{overflow:hidden;background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow)}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:20px;border-bottom:1px solid var(--line)}h2{margin:0;font-size:20px;font-weight:400}.count{color:var(--muted);font:12px Arial}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font:13px Arial}th{padding:13px 15px;background:#fbfdfc;color:var(--muted);text-align:left;font-size:10px;letter-spacing:.1em;text-transform:uppercase}td{padding:14px 15px;border-top:1px solid #edf2f3;white-space:nowrap}.barangay{color:var(--teal);font-weight:700}.diseases{display:inline-block;max-width:260px;white-space:normal;line-height:1.4}.pill{display:inline-flex;min-width:28px;justify-content:center;padding:4px 8px;border-radius:20px;background:#ecfdf5;color:#047857;font-weight:700}.attachment{display:inline-block;padding:5px 9px;border-radius:20px;background:#dcfce7;color:#166534;font-weight:700;font-size:11px}.missing{background:#f1f5f9;color:#64748b}.action{display:inline-block;padding:8px 11px;border-radius:4px;background:var(--teal);color:#fff;text-decoration:none;font:700 11px Arial}.empty{padding:50px;color:var(--muted);text-align:center}.footer{display:flex;justify-content:space-between;padding:15px 20px;color:var(--muted);font:12px Arial;border-top:1px solid var(--line)}.pagination a{margin-left:8px;color:var(--teal);text-decoration:none}@media(max-width:900px){.shell{grid-template-columns:1fr}.sidebar{min-height:auto;padding:14px 18px}.brand{padding:0 0 14px;border:0}.label,.side-footer{display:none}.nav{display:flex;overflow-x:auto}.nav a{white-space:nowrap}}@media(max-width:620px){.topbar{display:block}.profile{margin-top:16px}.summary{grid-template-columns:1fr}}
    .mark img{width:38px;height:38px;object-fit:contain;border-radius:10px;background:#fff}
    </style>
</head>
<body>
<div class="shell">
    <aside class="sidebar"><div class="brand"><div class="mark"><img src="{{ asset('images/tabacare-logo.png') }}" alt="TABACARE logo"></div><div><strong>TABACARE</strong><small>Administration</small></div></div><div class="label">Management</div><nav class="nav"><a href="{{ route('admin.dashboard') }}"><span class="nav-icon">&#9632;</span> Dashboard</a><a href="{{ route('admin.accounts') }}"><span class="nav-icon">&#9673;</span> Barangay accounts</a><a class="active" href="{{ route('admin.reports') }}"><span class="nav-icon">&#9776;</span> Barangay reports</a><a href="{{ route('admin.statistics') }}"><span class="nav-icon">&#9646;</span> Disease statistics</a><a href="{{ route('admin.patients') }}"><span class="nav-icon">&#9998;</span> List of patients</a></nav><div class="side-footer">Administrator access<br><strong>{{ $adminName }}</strong><a href="{{ route('admin.admin-accounts.index') }}" style="display:block;margin-top:12px;padding:9px 10px;border-radius:6px;background:rgba(255,255,255,.08);color:#d9e3ea;text-decoration:none;font:600 12px Arial">Admin accounts</a><form method="POST" action="{{ route('logout') }}" style="margin-top:12px">@csrf<button type="submit" style="width:100%;padding:9px;border:1px solid #dcebea;border-radius:6px;background:transparent;color:#aabac5;cursor:pointer;font:600 12px Arial">Log out</button></form></div></aside>
    <main class="main">
        <header class="topbar"><div><div class="eyebrow">Administration workspace</div><h1>Barangay reports</h1><p class="intro">Review reports and Excel attachments submitted by health workers.</p></div><div class="profile"><div class="avatar">{{ strtoupper(substr($adminName,0,1)) }}</div>{{ $adminName }}</div></header>
        <section class="summary"><article class="summary-card"><span class="summary-label">Reports received</span><span class="summary-value">{{ $reports->total() }}</span><small>Refresh to see new submissions</small></article><article class="summary-card"><span class="summary-label">Barangays reporting</span><span class="summary-value">{{ $barangayCount }}</span></article><article class="summary-card"><span class="summary-label">Total cases reported</span><span class="summary-value">{{ $totalCases }}</span></article></section>
        <section class="panel"><div class="panel-head"><h2>Submitted reports</h2><span class="count">{{ $reports->total() }} total</span></div>@if($reports->isEmpty())<div class="empty">No reports have been submitted yet.</div>@else<div class="table-wrap"><table><thead><tr><th>Report period</th><th>Barangay</th><th>Prepared by</th><th>Diseases included</th><th>Cases</th><th>Submitted</th><th>Attachment</th><th>Actions</th></tr></thead><tbody>@foreach($reports as $report)<tr><td>{{ $report->report_frequency === 'annual' ? 'Annual '.$report->report_period?->format('Y') : ($report->report_period?->format('F Y') ?? 'Unknown') }}</td><td class="barangay">{{ $report->barangay ?: 'Unknown' }}</td><td>{{ $report->prepared_by ?: 'Health worker #'.$report->worker_id }}</td><td><span class="diseases">{{ implode(', ', is_array($report->diseases) ? $report->diseases : (json_decode($report->diseases, true) ?: []) ) }}</span></td><td><span class="pill">{{ $report->patient_count ?? 0 }}</span></td><td>{{ $report->submitted_at?->format('M d, Y H:i') ?? 'Unknown' }}</td><td>@if($report->attachment_path)<span class="attachment">Attached</span>@else<span class="attachment missing">No file</span>@endif</td><td>@if($report->attachment_path)<a class="action" href="{{ route('admin.reports.attachment',$report) }}">Excel file</a>@else<a class="action" href="{{ route('admin.reports.download',$report) }}">Generate</a>@endif</td></tr>@endforeach</tbody></table></div><div class="footer"><span>Showing {{ $reports->firstItem() }} to {{ $reports->lastItem() }}</span><span class="pagination">{{ $reports->links() }}</span></div>@endif</section>
    </main>
</div>
